COLS = ["date", "open", "high", "low", "close", "volume", "amount"]
ok = 0
for sym, rows in RAW.items():
    f = OUT / f"{sym}.csv"
    if not f.exists():
        print(f"❌ {sym} 本地文件不存在，跳过")
        continue
    # 倒序 → 正序，映射 last→close
    new = pd.DataFrame([
        {"date": r[0], "open": r[1], "high": r[3], "low": r[4], "close": r[2], "volume": r[5], "amount": r[6]}
        for r in reversed(rows)
    ])
    old = pd.read_csv(f, dtype={"date": str})
    old["date"] = old["date"].astype(str)
    merged = pd.concat([old, new]).drop_duplicates(subset="date", keep="last")
    merged = merged.sort_values("date").reset_index(drop=True)
    # 保持原列序
    col_order = [c for c in COLS if c in merged.columns]
    merged = merged[col_order]
    merged.to_csv(f, index=False)
    ok += 1
    print(f"✅ {sym}: {len(old)}→{len(merged)} 行, 末日 {merged['date'].iloc[-1]}")
print(f"\n完成 {ok}/45 只")
